use split_decls_genesis :: ourprelude :: * ; use rustc_hir as hir ; use rustc_session :: { declare_lint , declare_lint_pass } ; use rustc_trait_selection :: error_reporting :: traits :: suggestions :: suggest_desugaring_async_fn_to_impl_future_in_trait ; use crate :: lints :: AsyncFnInTraitDiag ; use crate :: { LateContext , LateLintPass } ; declare_lint ! { #[doc = " The `async_fn_in_trait` lint detects use of `async fn` in the"] #[doc = " definition of a publicly-reachable trait."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " pub trait Trait {"] #[doc = "     async fn method(&self);"] #[doc = " }"] #[doc = " # fn main() {}"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " When `async fn` is used in a trait definition, the trait does not"] #[doc = " promise that the opaque [`Future`] returned by the associated function"] #[doc = " or method will implement any [auto traits] such as [`Send`]. This may"] #[doc = " be surprising and may make the associated functions or methods on the"] #[doc = " trait less useful than intended. On traits exposed publicly from a"] #[doc = " crate, this may affect downstream crates whose authors cannot alter"] #[doc = " the trait definition."] #[doc = ""] #[doc = " For example, this code is invalid:"] #[doc = ""] #[doc = " ```rust,compile_fail"] #[doc = " pub trait Trait {"] #[doc = "     async fn method(&self) {}"] #[doc = " }"] #[doc = ""] #[doc = " fn test<T: Trait>(x: T) {"] #[doc = "     fn spawn<T: Send>(_: T) {}"] #[doc = "     spawn(x.method()); // Not OK."] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " This lint exists to warn authors of publicly-reachable traits that"] #[doc = " they may want to consider desugaring the `async fn` to a normal `fn`"] #[doc = " that returns an opaque `impl Future<..> + Send` type."] #[doc = ""] #[doc = " For example, instead of:"] #[doc = ""] #[doc = " ```rust"] #[doc = " pub trait Trait {"] #[doc = "     async fn method(&self) {}"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " The author of the trait may want to write:"] #[doc = ""] #[doc = ""] #[doc = " ```rust"] #[doc = " use core::future::Future;"] #[doc = " pub trait Trait {"] #[doc = "     fn method(&self) -> impl Future<Output = ()> + Send { async {} }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " This still allows the use of `async fn` within impls of the trait."] #[doc = " However, it also means that the trait will never be compatible with"] #[doc = " impls where the returned [`Future`] of the method does not implement"] #[doc = " `Send`."] #[doc = ""] #[doc = " Conversely, if the trait is used only locally, if it is never used in"] #[doc = " generic functions, or if it is only used in single-threaded contexts"] #[doc = " that do not care whether the returned [`Future`] implements [`Send`],"] #[doc = " then the lint may be suppressed."] #[doc = ""] #[doc = " [`Future`]: https://doc.rust-lang.org/core/future/trait.Future.html"] #[doc = " [`Send`]: https://doc.rust-lang.org/core/marker/trait.Send.html"] #[doc = " [auto traits]: https://doc.rust-lang.org/reference/special-types-and-traits.html#auto-traits"] pub ASYNC_FN_IN_TRAIT , Warn , "use of `async fn` in definition of a publicly-reachable trait" } declare_lint_pass ! (#[doc = " Lint for use of `async fn` in the definition of a publicly-reachable"] #[doc = " trait."] AsyncFnInTrait => [ASYNC_FN_IN_TRAIT]) ; impl < 'tcx > LateLintPass < 'tcx > for AsyncFnInTrait { fn check_trait_item (& mut self , cx : & LateContext < 'tcx > , item : & 'tcx hir :: TraitItem < 'tcx >) { if let hir :: TraitItemKind :: Fn (sig , body) = item . kind && let hir :: IsAsync :: Async (async_span) = sig . header . asyncness { if cx . tcx . features () . return_type_notation () { return ; } if ! cx . tcx . effective_visibilities (()) . is_reachable (item . owner_id . def_id) { return ; } let hir :: FnRetTy :: Return (hir :: Ty { kind : hir :: TyKind :: OpaqueDef (opaq_def , ..) , .. }) = sig . decl . output else { return ; } ; let sugg = suggest_desugaring_async_fn_to_impl_future_in_trait (cx . tcx , sig , body , opaq_def . def_id , " + Send" ,) ; cx . tcx . emit_node_span_lint (ASYNC_FN_IN_TRAIT , item . hir_id () , async_span , AsyncFnInTraitDiag { sugg } ,) ; } } }